// The shared Rust core (crates/core-ffi) for Android: UniFFI Kotlin bindings and
// native libraries, both generated by scripts/build-android-core.sh (gitignored).
plugins {
    alias(libs.plugins.android.library)
}

android {
    namespace = "io.passauth.core"
    compileSdk = 36

    defaultConfig {
        minSdk = 34
        consumerProguardFiles("consumer-rules.pro")
        ndk { abiFilters += listOf("arm64-v8a", "x86_64") }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

kotlin {
    compilerOptions { jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17) }
}

val bindings = file("src/main/kotlin/io/passauth/core/passauth_ffi.kt")
val nativeLib = file("src/main/jniLibs/arm64-v8a/libpassauth_ffi.so")
tasks.named("preBuild") {
    doFirst {
        check(bindings.exists() && nativeLib.exists()) {
            "PassAuth core not built. Run scripts/build-android-core.sh from the repository root first."
        }
    }
}

dependencies {
    api(variantOf(libs.jna) { artifactType("aar") })
}
